    textarea.value = text;
    textarea.setAttribute('readonly', '');
    textarea.style.position = 'fixed';
    textarea.style.top = '-1000px';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();
    textarea.setSelectionRange(0, text.length);
    let copied = false;
    try {
      copied = document.execCommand('copy');
    } catch (_) {
      copied = false;
    }
    document.body.removeChild(textarea);
    if (copied) {
      button.textContent = 'Copied!';
      announce(announcementId, 'Site freshness copied to clipboard');
    } else {
      button.textContent = 'Failed';
      announce(announcementId, 'Copy failed');
    }
    resetButton(button, announcementId);
  }

  function copyFreshness(button) {
    const detail = document.getElementById('site-freshness-detail');
    const text = detail ? detail.textContent.trim() : '';
    const announcementId = 'copy-freshness-announcement';
    if (!text) { ... return; }
    const clipboard = navigator.clipboard;
    if (clipboard && typeof clipboard.writeText === 'function') {
      try {
        clipboard.writeText(text).then(
          function () {
            button.textContent = 'Copied!';
            announce(...);
            resetButton(...);
          },
          function () { copyWithFallback(...); }
        );
      } catch (_) {
        copyWithFallback(...);
      }
    } else {
      copyWithFallback(...);
    }
  }

  function initialize() {
    const button = document.getElementById('copy-freshness');
    if (button) button.addEventListener('click', function () { copyFreshness(button); });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialize);
  } else {
    initialize();
  }
}());
